import{_ as r,c as a,o as t,j as s,Y as n,t as i}from"./chunks/framework.BNTND4LZ.js";const k=JSON.parse('{"title":"docker-login | x-cmd man (docker man1) | Log in to a registry","titleTemplate":false,"description":"x-cmd man (docker man1 Manual Page) | docker-login - Log in to a registry","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"docker-login | x-cmd man (docker man1) | Log in to a registry"}],["meta",{"name":"og:description","content":"x-cmd man (docker man1 Manual Page) | docker-login - Log in to a registry"}]]},"headers":[],"params":{"isMan":true,"man":"docker-login","category":"docker man1","desc":"Log in to a registry"},"relativePath":"docker/man1/docker-login.md","filePath":"docker/man1/[man].md"}'),c={name:"docker/man1/docker-login.md"},l={class:"visually-hidden"};function d(e,o,g,h,p,u){return t(),a("div",null,[s("h1",l,i(e.$params.man),1),o[0]||(o[0]=n('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>docker-login - Log in to a registry</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p><strong>docker login [OPTIONS] [SERVER]</strong></p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Log in to a Docker Registry located on the specified <strong>SERVER</strong>. You can specify a URL or a <strong>hostname</strong> for the <strong>SERVER</strong> value. If you do not specify a <strong>SERVER</strong>, the command uses Docker&#39;s public registry located at <strong><a href="https://registry-1.docker.io/" target="_blank" rel="noreferrer">https://registry-1.docker.io/</a></strong> by default. To get a username/password for Docker&#39;s public registry, create an account on Docker Hub.</p><p><strong>docker login</strong> requires user to use <strong>sudo</strong> or be <strong>root</strong>, except when:</p><blockquote><ol><li></li></ol><p>: connecting to a remote daemon, such as a <strong>docker-machine</strong> provisioned <strong>docker engine</strong>.</p><ol start="2"><li></li></ol><p>: user is added to the <strong>docker</strong> group. This will impact the security of your system; the <strong>docker</strong> group is <strong>root</strong> equivalent. See Docker Daemon Attack Surface ⟨<a href="https://docs.docker.com/engine/security/#docker-daemon-attack-surface%E2%9F%A9" target="_blank" rel="noreferrer">https://docs.docker.com/engine/security/#docker-daemon-attack-surface⟩</a> for details.</p></blockquote><p>You can log into any public or private repository for which you have credentials. When you log in, the command stores encoded credentials in <strong>$HOME/.docker/config.json</strong> on Linux or <strong>%USERPROFILE%/.docker/config.json</strong> on Windows.</p><h2 id="examples" tabindex="-1">EXAMPLES <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;EXAMPLES&quot;">​</a></h2><h2 id="login-to-a-registry-on-your-localhost" tabindex="-1">Login to a registry on your localhost <a class="header-anchor" href="#login-to-a-registry-on-your-localhost" aria-label="Permalink to &quot;Login to a registry on your localhost&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># docker login localhost:8080</span></span></code></pre></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><p><strong>docker-logout(1)</strong> to log out from a registry.</p><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><p><strong>-h</strong>, <strong>--help</strong>[=false] help for login</p><p><strong>-p</strong>, <strong>--password</strong>=&quot;&quot; Password</p><p><strong>--password-stdin</strong>[=false] Take the password from stdin</p><p><strong>-u</strong>, <strong>--username</strong>=&quot;&quot; Username</p><h2 id="see-also-1" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also-1" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>docker(1)</strong></p>',21))])}const f=r(c,[["render",d]]);export{k as __pageData,f as default};
